#define main previous_main
#include "native_instrument.cpp"
#undef main
int main(int argc,char**argv){if(argc<2)return 2;try{re::Core c("",0,argv[1]);ready(c);float l[512]{},r[512]{};int cases=0;for(int engine=0;engine<20;engine++)for(bool pedal:{false,true}){c.set(1,engine/19.f);ready(c);c.tempo(120,0,true);int root=engine==0?36:60;if(pedal)c.midi(0xb0,64,127);for(int key:{root,root+2,root+7})c.midi(0x90,key,112);for(int b=0;b<32;b++)c.render(l,r,512);if(pedal)for(int key:{root,root+2,root+7})c.midi(0x80,key,0);c.tempo(120,.5,false);double peak=0;for(int b=0;b<90;b++){c.render(l,r,512);for(int i=0;i<512;i++)peak=std::max(peak,double(std::max(std::abs(l[i]),std::abs(r[i]))));}if(peak>1e-7)throw std::runtime_error("Residual audio engine "+std::to_string(engine));c.tempo(120,0,true);for(int b=0;b<8;b++){c.render(l,r,512);for(int i=0;i<512;i++)if(std::abs(l[i])+std::abs(r[i])>1e-7)throw std::runtime_error("Restart ghost note");}c.tempo(120,0,false);cases++;}std::cout<<"TRANSPORT_ALL_PASS engines=20 cases="<<cases<<" held_chords,sustain,restart_no_notes residual=0\n";}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
